int op_bind(const char *a, struct Lay *b) {
  struct stat st;
  if (stat(a, &st) != 0) return -1;

  memset(b, 0, sizeof(*b));
  if (strlen(a) >= sizeof(b->path)) return -1;
  strcpy(b->path, a);
  b->dev = (unsigned long long)st.st_dev;
  b->ino = (unsigned long long)st.st_ino;

  /* Identity and timestamps do not identify file contents: tamp deliberately
     rewrites this inode in place and normalizes its timestamp. */
  if (file_sha256_hex(a, b->dig) != 0) return -1;
  if (fill_text(a, &b->vma, &b->off, &b->sz) != 0) return -1;
  if (write_row(b) != 0) return -1;
  return 0;
}
